namespace asio=boost::asio;namespace beast=boost::beast;namespace http=beast::http;using tcp=asio::ip::tcp;
class FaultProxy {
 asio::io_context io_;tcp::acceptor acceptor_;int core_;std::thread thread_;std::atomic<bool> stopped_=false;
 void serve(){while(!stopped_){tcp::socket socket(io_);boost::system::error_code error;acceptor_.accept(socket,error);if(error==asio::error::would_block||error==asio::error::try_again){std::this_thread::sleep_for(5ms);continue;}if(error)continue;
  try{beast::flat_buffer buffer;http::request_parser<http::string_body> parser;parser.body_limit(16*1024*1024);http::read(socket,buffer,parser);auto request=Json::parse(parser.get().body());std::string method=request["method"];auto params=request.value("params",Json::array());
   {std::unique_lock guard(mutex);if(method=="validator_submitBlock"&&hold_next){held_block=params[0];held=true;condition.notify_all();condition.wait_for(guard,10s,[&]{return released||stopped_;});socket.close();continue;}if(method=="validator_submitBlock"&&dropped.is_null()){dropped=params[0];socket.shutdown(tcp::socket::shutdown_both,error);socket.close();continue;}}
   auto result=rpc(core_,method,params);
   {std::lock_guard guard(mutex);if(method=="eth_getBlockByNumber"&&params[0]=="0x1"&&corrupt_parent)result["producerProof"]["signature"]="0x"+std::string(130,'0');if(method=="validator_getBlockTemplate"){if(corrupt)result["stateRoot"]="0x"+std::string(64,'0');++templates;result["timestamp"]=quantity(Int(quantity(result["timestamp"])+templates));result.erase("hash");}}
   http::response<http::string_body> response(http::status::ok,11);response.body()=Json{{"jsonrpc","2.0"},{"id",request["id"]},{"result",result}}.dump();response.prepare_payload();http::write(socket,response);
  }catch(const std::exception&){/* Deliberately closed client connections are part of the fault scenario. */}
 }}
public:
 std::mutex mutex;std::condition_variable condition;Json dropped=nullptr,held_block=nullptr;bool corrupt=true,corrupt_parent=true,hold_next=false,held=false,released=false;int templates=0;
 explicit FaultProxy(int port):acceptor_(io_,tcp::endpoint(asio::ip::make_address("127.0.0.1"),0)),core_(port){acceptor_.non_blocking(true);thread_=std::thread([this]{serve();});}
 ~FaultProxy(){stopped_=true;{std::lock_guard guard(mutex);released=true;}condition.notify_all();thread_.join();}
 int port()const{return acceptor_.local_endpoint().port();}
};
int main(int argc,char** argv){try{check(argc==2,"nano required");std::string binary=argv[1];Temp root;Env env={{"VALIDATOR_KEY",key()},{"NANO_WALLET_PASSWORD","fixture-only"},{"NANO_PRIVATE_KEY",key()}};auto genesis=root/"genesis.json";save(genesis,{{"config",{{"chainId",1337},{"consensus","pos"},{"posSignatureVersion",1},{"bootstrapValidator",address(account)}}}});
 auto command=[&](std::vector<std::string> args,bool ok=true){args.insert(args.begin(),binary);auto r=run(args,env);check((r.code==0)==ok,r.err+r.out);return r;};auto status=success(command({"init",genesis.string(),(root/"db").string()}));auto genesis_hash=status["blockHash"];auto first=success(command({"validate",genesis.string(),(root/"db").string(),address(account),"12"}));check(first["producerProof"]["version"]==1,"signed CLI proof");auto file=root/"block.json";save(file,first);command({"import",genesis.string(),(root/"peer").string(),file.string(),"12"});check(success(command({"status",genesis.string(),(root/"peer").string()}))["blockHash"]==first["hash"],"CLI import hash");auto audit=success(command({"audit",genesis.string(),(root/"peer").string()}));check(audit["verified"]&&audit["blocks"]==2,"import audit");check(command({"audit",genesis.string(),(root/"absent").string()},false).err.find("existing RocksDB")!=std::string::npos&&!fs::exists(root/"absent"),"audit created database");
 Process server({binary,"serve",genesis.string(),(root/"db").string(),"0","127.0.0.1"},env);int port=server.port();auto config=root/"validator.json";Json base={{"nodes",Json::array({url(port)})},{"max_retries",1},{"signing_db",(root/"journal").string()},{"genesis_file",genesis.string()},{"verification_db",(root/"verification").string()}};auto once=[&](bool ok=true){save(config,base);return command({"validator",config.string(),"--once"},ok);};check(once(false).err.find("requires chain_id and genesis_hash")!=std::string::npos,"unpinned validator accepted");base["chain_id"]=1338;base["genesis_hash"]=genesis_hash;check(once(false).err.find("identity mismatch")!=std::string::npos&&rpc(port,"eth_blockNumber")=="0x1","wrong chain accepted");base["chain_id"]=1337;base["genesis_hash"]="0x"+std::string(64,'0');check(once(false).err.find("identity mismatch")!=std::string::npos,"wrong genesis accepted");base["register"]=true;base["staking_contract"]=address(account);check(once(false).err.find("identity mismatch")!=std::string::npos&&rpc(port,"eth_getTransactionCount",{account,"pending"})=="0x0","registration preceded identity check");base.erase("register");base.erase("staking_contract");base["genesis_hash"]=genesis_hash;
 FaultProxy proxy(port);base["nodes"]=Json::array({url(proxy.port())});check(once(false).err.find("invalid or missing PoS producer signature")!=std::string::npos,"forged parent not detected");{std::lock_guard guard(proxy.mutex);check(proxy.dropped.is_null(),"signed before parent verification");proxy.corrupt_parent=false;}
 check(once(false).err.find("block execution commitments mismatch")!=std::string::npos,"invalid execution template accepted");{std::lock_guard guard(proxy.mutex);check(proxy.dropped.is_null(),"signed invalid template");proxy.corrupt=false;}check(rpc(port,"eth_blockNumber")=="0x1","forgery changed tip");once(false);Json dropped;{std::lock_guard guard(proxy.mutex);dropped=proxy.dropped;}check(!dropped.is_null()&&rpc(port,"eth_blockNumber")=="0x1","drop failed");check(success(once())["success"]&&rpc(port,"eth_getBlockByNumber",{"latest",true})["hash"]==dropped["hash"],"retry signed different block");auto block=rpc(port,"eth_getBlockByNumber",{"latest",true});check(block["producerProof"]["version"]==1&&rpc(port,"eth_accounts")==Json::array()&&rpc(port,"eth_blockNumber")=="0x2","remote signed production");block.erase("producerProof");check(!rpc(port,"validator_submitBlock",{block})["success"].get<bool>(),"missing proof admitted");
 {std::lock_guard guard(proxy.mutex);proxy.hold_next=true;}Process interrupted({binary,"validator",config.string(),"--once"},env);{std::unique_lock guard(proxy.mutex);check(proxy.condition.wait_for(guard,10s,[&]{return proxy.held;}),"submission not intercepted");}check(interrupted.running()&&rpc(port,"eth_blockNumber")=="0x2","premature submission");interrupted.signal(SIGKILL);check(interrupted.wait(5).code==-SIGKILL,"not an abrupt validator stop");Json held;{std::lock_guard guard(proxy.mutex);held=proxy.held_block;proxy.hold_next=false;proxy.released=true;}proxy.condition.notify_all();check(success(once())["success"]&&rpc(port,"eth_blockNumber")=="0x3","restart failed");auto recovered=rpc(port,"eth_getBlockByNumber",{"latest",true});check(recovered["hash"]==held["hash"]&&recovered["producerProof"]==held["producerProof"],"SIGKILL recovery changed signature");check(success(command({"audit",genesis.string(),(root/"verification").string()}))["verified"],"verification audit failed");
 base["nodes"]=Json::array({url(port)});base["block_time"]=1;save(config,base);Process continuous({binary,"validator",config.string()},env);until([&]{return quantity(rpc(port,"eth_blockNumber"))>=5;},"continuous validator progresses",12);auto locked=command({"audit",genesis.string(),(root/"verification").string()},false).err;std::transform(locked.begin(),locked.end(),locked.begin(),[](unsigned char c){return std::tolower(c);});check(locked.find("lock")!=std::string::npos,"verification database not held open");check(continuous.stop().code==0,"continuous validator shutdown");check(success(command({"audit",genesis.string(),(root/"verification").string()}))["verified"],"verification audit after stop");
 auto wallet=root/"wallet.json",local=root/"local.json";command({"wallet","import",wallet.string()});save(local,{{"coinbase",address(account)},{"block_time",1},{"wallets",Json::array({Json{{"path",wallet.string()},{"password_env","NANO_WALLET_PASSWORD"}}})}});Process automatic({binary,"serve",genesis.string(),(root/"auto-db").string(),"0","127.0.0.1",local.string()},env);int local_port=automatic.port();check(rpc(local_port,"nno_startValidating"),"automatic start");until([&]{return rpc(local_port,"eth_blockNumber")!="0x0";},"wallet producer advances",8);check(rpc(local_port,"nno_stopValidating"),"automatic stop");auto produced=rpc(local_port,"eth_getBlockByNumber",{"latest",true});check(produced["number"]!="0x0"&&produced["producerProof"]["version"]==1,"automatic unsigned block");std::cout<<"Native signed validator adversarial scenarios passed\n";
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
